/*
 * mlp_core.h — Portable MLP inference engine for MCU
 *
 * Zero heap allocation. All buffers are compile-time static arrays.
 * Double-buffered ping-pong scheme for zero-copy layer chaining.
 *
 * Usage:
 *   #include "model.h"       // generated by training pipeline
 *   #include "mlp_core.h"
 *
 *   float output[MLP_OUTPUT_DIM];
 *   mlp_forward(input, output);
 *
 * Based on patterns from microgpt-c:
 *   - linear_fwd dispatch (microgpt-c lines 279-304)
 *   - ReLU² activation   (microgpt-c lines 444-447)
 *   - RMSNorm             (microgpt-c lines 307-318)
 */

#ifndef MLP_CORE_H
#define MLP_CORE_H

#include "mlp_platform.h"

#ifndef MLP_MAX_HIDDEN
  #define MLP_MAX_HIDDEN 128
#endif

#ifndef MLP_MAX_INPUT
  #define MLP_MAX_INPUT  32
#endif

#ifndef MLP_MAX_OUTPUT
  #define MLP_MAX_OUTPUT 16
#endif

/* ================================================================== */
/* Runtime scratch buffers (SRAM, zero-initialized)                     */
/* Double-buffered: layer i reads from one, writes to the other.       */
/* ================================================================== */

static float mlp_buf_a[MLP_MAX_HIDDEN];
static float mlp_buf_b[MLP_MAX_HIDDEN];

/* ================================================================== */
/* Activation function dispatch                                        */
/* ================================================================== */

static inline void mlp_activate(float *x, int n, mlp_act_t act, float clip_val) {
  switch (act) {
    case MLP_ACT_RELU:
      for (int i = 0; i < n; i++)
        x[i] = x[i] > 0.0f ? x[i] : 0.0f;
      break;

    case MLP_ACT_RELU2: /* microgpt-c: h2[i] = h1[i] > 0 ? h1[i]*h1[i] : 0 */
      for (int i = 0; i < n; i++)
        x[i] = x[i] > 0.0f ? x[i] * x[i] : 0.0f;
      break;

    case MLP_ACT_TANH:
      for (int i = 0; i < n; i++)
        x[i] = MLP_TANHF(x[i]);
      break;

    case MLP_ACT_SIGMOID:
      for (int i = 0; i < n; i++)
        x[i] = MLP_SIGMOIDF(x[i]);
      break;

    case MLP_ACT_CLIPPED_RELU:
      for (int i = 0; i < n; i++) {
        x[i] = x[i] > 0.0f ? x[i] : 0.0f;
        if (x[i] > clip_val) x[i] = clip_val;
      }
      break;

    case MLP_ACT_NONE:
    default:
      break;
  }
}

/* ================================================================== */
/* MLP Layer configuration (compile-time, defined in model.h)          */
/* ================================================================== */

#ifndef MLP_N_LAYERS
  #define MLP_N_LAYERS     3
#endif

#ifndef MLP_INPUT_DIM
  #define MLP_INPUT_DIM    12
#endif

#ifndef MLP_OUTPUT_DIM
  #define MLP_OUTPUT_DIM   1
#endif

/* Layer dimensions: each layer has n_in and n_out */
#ifndef MLP_LAYER_DIMS
  #define MLP_LAYER_DIMS  {64, 64, 16, 1}  /* hidden dims + output dim */
#endif

/* Activation per layer */
#ifndef MLP_LAYER_ACTS
  #define MLP_LAYER_ACTS  {MLP_ACT_RELU2, MLP_ACT_RELU2, MLP_ACT_RELU2, MLP_ACT_TANH}
#endif

/* Whether to apply RMSNorm before each hidden layer's linear transform */
#ifndef MLP_USE_RMSNORM
  #define MLP_USE_RMSNORM 0
#endif

/* ================================================================== */
/* Forward pass — full network                                         */
/* ================================================================== */

/*
 * mlp_forward_f32: pure float32 forward pass
 *
 * Requires model.h to define:
 *   const float mlp_w[N_LAYERS][dim_out][dim_in]   — weights
 *   const float mlp_b[N_LAYERS][dim_out]           — biases
 *   mlp_act_t mlp_acts[N_LAYERS]                   — activation per layer
 *   int mlp_dims[N_LAYERS]                         — n_out per layer
 */
static inline void mlp_forward_f32(const float *input, float *output) {
  /* Layer dimensions and activations — model.h must provide these */
  static const int     layer_dims[MLP_N_LAYERS] = MLP_LAYER_DIMS;
  static const mlp_act_t layer_acts[MLP_N_LAYERS] = MLP_LAYER_ACTS;

  /* Pointer arrays to weights and biases — model.h must provide extern */
  /* User must define these before including mlp_core.h, or define MLP_MODEL_DEFINED */
  extern const float *const mlp_weights[MLP_N_LAYERS];
  extern const float *const mlp_biases[MLP_N_LAYERS];

  /* Double-buffer pointers */
  float *src = mlp_buf_a;
  float *dst = mlp_buf_b;

  /* Copy input to first buffer */
  int n_in = MLP_INPUT_DIM;
  for (int i = 0; i < n_in; i++) src[i] = input[i];

  for (int li = 0; li < MLP_N_LAYERS; li++) {
    int n_out = layer_dims[li];

    /* Optional RMSNorm (pre-norm) */
#if MLP_USE_RMSNORM
    float norm_buf[MLP_MAX_HIDDEN];
    MLP_RMSNORM_FWD(src, n_in, norm_buf);
    MLP_LINEAR_FWD(norm_buf, mlp_weights[li], mlp_biases[li], n_out, n_in, dst);
#else
    MLP_LINEAR_FWD(src, mlp_weights[li], mlp_biases[li], n_out, n_in, dst);
#endif

    /* Activation (except possibly last layer — controlled by model) */
    mlp_activate(dst, n_out, layer_acts[li], 0.0f);

    /* Swap buffers */
    float *tmp = src;
    src = dst;
    dst = tmp;

    n_in = n_out;
  }

  /* Result is in src (after last swap) */
  int out_dim = layer_dims[MLP_N_LAYERS - 1];
  for (int i = 0; i < out_dim; i++) output[i] = src[i];
}

/* ================================================================== */
/* Simplified forward pass — inline model weights (no extern arrays)   */
/* ================================================================== */

/*
 * mlp_forward_inline: for models where weights are directly embedded
 * as const arrays in model.h (more common for small MCU models).
 *
 * model.h must define:
 *   const float mlp_w0[H0][N_IN], mlp_b0[H0]
 *   const float mlp_w1[H1][H0],  mlp_b1[H1]
 *   ...
 *   const float mlp_w_out[N_OUT][H_last], mlp_b_out[N_OUT]
 *
 * This variant is unrolled at compile time for zero-overhead dispatch.
 * Recommended for models with N_LAYERS <= 4.
 */
#if MLP_N_LAYERS == 1
  /* Single-layer: input -> output directly */
  #define MLP_FORWARD_INLINE(in, out) do { \
    extern const float mlp_w0[]; extern const float mlp_b0[]; \
    static const mlp_act_t acts[] = MLP_LAYER_ACTS; \
    float buf[MLP_LAYER_DIMS_ARR[0]]; \
    MLP_LINEAR_FWD(in, mlp_w0, mlp_b0, MLP_LAYER_DIMS_ARR[0], MLP_INPUT_DIM, buf); \
    mlp_activate(buf, MLP_LAYER_DIMS_ARR[0], acts[0], 0.0f); \
    for (int _i = 0; _i < MLP_OUTPUT_DIM; _i++) (out)[_i] = buf[_i]; \
  } while(0)

#elif MLP_N_LAYERS == 2
  #define MLP_FORWARD_INLINE(in, out) do { \
    extern const float mlp_w0[]; extern const float mlp_b0[]; \
    extern const float mlp_w_out[]; extern const float mlp_b_out[]; \
    static const mlp_act_t acts[] = MLP_LAYER_ACTS; \
    float buf_a[MLP_MAX_HIDDEN], buf_b[MLP_MAX_HIDDEN]; \
    int d0 = ((const int[])MLP_LAYER_DIMS)[0]; \
    int d1 = ((const int[])MLP_LAYER_DIMS)[1]; \
    MLP_LINEAR_FWD(in, mlp_w0, mlp_b0, d0, MLP_INPUT_DIM, buf_a); \
    mlp_activate(buf_a, d0, acts[0], 0.0f); \
    MLP_LINEAR_FWD(buf_a, mlp_w_out, mlp_b_out, d1, d0, buf_b); \
    mlp_activate(buf_b, d1, acts[1], 0.0f); \
    for (int _i = 0; _i < MLP_OUTPUT_DIM; _i++) (out)[_i] = buf_b[_i]; \
  } while(0)

#endif /* MLP_N_LAYERS specific variants */

/* ================================================================== */
/* Int8 hybrid forward pass                                            */
/* ================================================================== */

/*
 * mlp_forward_int8: hybrid inference (int8 weights, float32 activations)
 *
 * model.h must define (in addition to float32 versions):
 *   const int8_t  mlp_w0_q[H0][N_IN];  const float mlp_w0_s[H0];
 *   ...
 *   const float   mlp_b0[H0];           (biases stay float32)
 */
static inline void mlp_forward_int8(const float *input, float *output) {
  static const int     layer_dims[MLP_N_LAYERS] = MLP_LAYER_DIMS;
  static const mlp_act_t layer_acts[MLP_N_LAYERS] = MLP_LAYER_ACTS;

  extern const int8_t *const mlp_weights_q[MLP_N_LAYERS];
  extern const float  *const mlp_biases[MLP_N_LAYERS];
  extern const float  *const mlp_scales[MLP_N_LAYERS];

  float *src = mlp_buf_a;
  float *dst = mlp_buf_b;

  int n_in = MLP_INPUT_DIM;
  for (int i = 0; i < n_in; i++) src[i] = input[i];

  for (int li = 0; li < MLP_N_LAYERS; li++) {
    int n_out = layer_dims[li];
    mlp_linear_fwd_int8(src, mlp_weights_q[li], mlp_biases[li],
                         mlp_scales[li], n_out, n_in, dst);
    mlp_activate(dst, n_out, layer_acts[li], 0.0f);

    float *tmp = src; src = dst; dst = tmp;
    n_in = n_out;
  }

  int out_dim = layer_dims[MLP_N_LAYERS - 1];
  for (int i = 0; i < out_dim; i++) output[i] = src[i];
}

#endif /* MLP_CORE_H */
